class BaseLLMProvider(ABC):
    def __init__(self, config: dict):
        self.config = config
        self._request_count = 0
        self._total_tokens = 0
        self._total_cost = 0.0

    @property
    @abstractmethod
    def provider_name(self) -> str: ...

    @abstractmethod
    async def generate(self, messages: list[LLMMessage], temperature: float = 0.7, max_tokens: int = 4096, **kwargs) -> LLMResponse: ...

    @abstractmethod
    async def stream(self, messages: list[LLMMessage], temperature: float = 0.7, max_tokens: int = 4096, **kwargs) -> AsyncIterator[str]: ...

    @abstractmethod
    def count_tokens(self, text: str) -> int: ...

    def calculate_cost(self, input_tokens: int, output_tokens: int) -> float:
        input_cost = (input_tokens / 1000) * self.config.get("input_cost_per_1k", 0)
        output_cost = (output_tokens / 1000) * self.config.get("output_cost_per_1k", 0)
        return round(input_cost + output_cost, 6)

    def get_stats(self) -> dict:
        return {"provider": self.provider_name, "request_count": self._request_count, "total_tokens": self._total_tokens, "total_cost": self._total_cost}

class ProviderFactory:
    def __init__(self, settings):
        self.settings = settings
        self._registry: dict[str, Type[BaseLLMProvider]] = {}
        self._instances: dict[str, BaseLLMProvider] = {}
        self._circuit_breakers: dict[str, CircuitBreaker] = {}

    def register(self, name: str, provider_class: Type[BaseLLMProvider]):
        self._registry[name] = provider_class
        self._circuit_breakers[name] = CircuitBreaker()

    def get_provider(self, name: str) -> BaseLLMProvider:
        if name not in self._instances:
            if name not in self._registry:
                raise ValueError(f"Bilinmeyen provider: {name}")
            config = getattr(self.settings, name, {})
            self._instances[name] = self._registry[name](config)
        return self._instances[name]

    async def generate_with_fallback(self, messages: list[LLMMessage], preferred_provider: str | None = None, **kwargs) -> LLMResponse:
        providers_to_try = []
        if preferred_provider: providers_to_try.append(preferred_provider)
        for p in self.settings.fallback_providers:
            if p.value not in providers_to_try: providers_to_try.append(p.value)
        last_error = None
        for provider_name in providers_to_try:
            cb = self._circuit_breakers.get(provider_name)
            if cb and not cb.can_execute(): continue
            try:
                provider = self.get_provider(provider_name)
                start_time = time.time()
                response = await provider.generate(messages, **kwargs)
                response.latency_ms = (time.time() - start_time) * 1000
                if cb: cb.record_success()
                return response
            except Exception as e:
                last_error = e
                if cb: cb.record_failure()
                continue
        raise RuntimeError(f"Tuem provider'lar basarisiz oldu. Son hata: {last_error}")

